using System;
using System.Linq;
using System.Collections.Generic;
using System.Reflection;
using System.Threading.Tasks;
using UnityEngine;
using UnityEditor;
using UnityEngine.SceneManagement;
using Polarity.Simulation;
using Polarity.Controllers;
using Polarity.Entities;
using Polarity.Views;
using Polarity.Model;
using UnityEngine.UI;
using Codely.Newtonsoft.Json;
EditorApplication.isPaused=true;
var flags=BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic;
int Listeners(object o,string key)=>((Delegate)o.GetType().GetField(key,flags).GetValue(o))?.GetInvocationList().Length??0;
var checks=new List<object>();
void Check(string name,bool pass,object evidence=null){checks.Add(new{name,pass,evidence});}
var modes=new[]{"RunningSlow","PausedHeld","PausedReleased","Won","Lost","RunningAgain"};
var baseline=JsonConvert.DeserializeObject<Dictionary<string,float[]>>(@"{""Player"": [5.0, -2.5], ""Enemy"": [-3.0, 0.0], ""Enemy_02"": [-5.5, 1.8], ""Enemy_03"": [-5.5, 0.0], ""Enemy_04"": [-5.5, -1.8], ""Enemy_05"": [-3.5, 2.4], ""Enemy_06"": [-3.5, -2.4], ""Crate"": [3.0, 0.0]}");
async Task<string> Run(){
 foreach(var mode in modes){
  var old=Object.FindObjectOfType<SimulationWorld>();var oldHud=Object.FindObjectOfType<HUDView>();var oldState=old.State;var oldHealth=old.PlayerHealth;
  old.Level.enabled=false;old.Level.SampleControlInput(false,false,false);old.Level.SampleControlInput(true,false,false);
  old.Player.Rigidbody.position=new Vector2(4,-3);old.Player.Rigidbody.velocity=Vector2.zero;
  var prefab=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Polarity/Prefabs/Actors/Projectile.prefab").GetComponent<Projectile>();
  var shot=(Projectile)typeof(SimulationWorld).GetMethod("SpawnProjectile",flags).Invoke(old,new object[]{prefab,new Vector2(1,-3),Vector2.right,0f});
  old.SubmitMark(7,Polarity.Model.Polarity.Positive);old.Player.SampleMoveInput(false,false,false,true);
  if(mode.StartsWith("Paused"))old.Level.SampleControlInput(true,true,false);
  if(mode=="PausedReleased")old.Level.SampleControlInput(false,false,false);
  if(mode=="Won"||mode=="Lost")old.SetPhase(mode=="Won"?LevelPhase.Won:LevelPhase.Lost);
  bool oldPhaseCorrect=old.State.Phase.ToString()==(mode.StartsWith("Paused")?"Paused":mode=="Won"||mode=="Lost"?mode:"Running");
  bool requested=false;
  void OnLoaded(Scene scene,LoadSceneMode load){
   EditorApplication.isPaused=true;
   var fresh=Object.FindObjectOfType<SimulationWorld>();fresh.Level.enabled=false;
   bool positions=(fresh.Player.Rigidbody.position-new Vector2(baseline["Player"][0],baseline["Player"][1])).sqrMagnitude<.000001f;
   foreach(var b in fresh.Bodies)positions&=(b.Rigidbody.position-new Vector2(baseline[b.name][0],baseline[b.name][1])).sqrMagnitude<.000001f;
   Check(mode+" initial room state restored at sceneLoaded",positions&&fresh.State.Phase==LevelPhase.Running&&fresh.State.RemainingMarks==3&&fresh.State.ActiveEnemyCount==6&&fresh.PlayerHealth.CurrentHealth==3&&fresh.PlayerHealth.NextDamageTime==0&&fresh.Bodies.Count==7&&fresh.Bodies.All(b=>b.BodyId==7?b.CurrentPolarity==Polarity.Model.Polarity.Negative:b.CurrentPolarity==Polarity.Model.Polarity.Neutral),new {positions,fresh.CompletedStepCount});
   Check(mode+" clean queues timers and dynamic IDs at sceneLoaded",fresh.PendingMarkCount==0&&fresh.ProcessedMarkCount==0&&fresh.SimulationTime==0&&fresh.CompletedStepCount==0&&fresh.ActiveProjectileCount==0&&fresh.SpawnedProjectileCount==0&&fresh.ConsumedProjectileCount==0&&fresh.Turrets[0].ShotsFired==0&&fresh.LastPropagation==null&&fresh.LastMarkResult==null&&fresh.LastDamageResults.Count==0&&fresh.LastContactPairs.Count==0&&fresh.Bodies.Select(b=>b.BodyId).SequenceEqual(Enumerable.Range(1,7)));
  }
  SceneManager.sceneLoaded+=OnLoaded;
  EditorApplication.isPaused=false;
  if(mode=="RunningAgain"){old.Level.SampleControlInput(true,true,true);requested=old.Level.IsRestarting;}
  else requested=old.Level.RequestRestart();
  bool duplicate=!old.Level.RequestRestart();
  SimulationWorld current=null;
  for(int i=0;i<800;i++){await Task.Delay(10);current=Object.FindObjectOfType<SimulationWorld>();if(current!=null&&current!=old&&current.OwnsPhysics)break;}
  SceneManager.sceneLoaded-=OnLoaded;
  if(current==null||current==old)throw new Exception("Retry timeout");
  var h=Object.FindObjectOfType<HUDView>();
  // All OnEnable bindings are available; invoke no world mutation to make the HUD valid.
  Check(mode+" reload and old references released",oldPhaseCorrect&&requested&&duplicate&&old==null&&oldHud==null&&shot==null&&Listeners(oldState,"PhaseChanged")==0&&Listeners(oldState,"MarksChanged")==0&&Listeners(oldState,"EnemyCountChanged")==0,new {requested,duplicate,oldDestroyed=old==null});
  Check(mode+" one World HUD and paired subscriptions",Object.FindObjectsOfType<SimulationWorld>().Length==1&&Object.FindObjectsOfType<HUDView>().Length==1&&h.IsBound&&!h.ModalVisible&&Listeners(current,"MarkResolved")==1&&Listeners(current,"PropagationCommitted")==1&&Listeners(current,"TimeScaleChanged")==1&&Listeners(current.State,"PhaseChanged")==2&&Listeners(current.PlayerHealth,"HealthChanged")==1);
  current.Level.enabled=false;current.Level.SampleControlInput(true,false,false);
  Check(mode+" held Space after retry stays normal",Time.timeScale==1&&!current.SlowMotionRequested&&current.Player.MoveIntent==Vector2.zero&&Mathf.Approximately(Time.fixedDeltaTime,.02f));
  current.Level.SampleControlInput(false,false,false);current.Level.SampleControlInput(true,false,false);
  Check(mode+" release then press rearms slow",Mathf.Approximately(Time.timeScale,.3f));current.Level.SampleControlInput(false,false,false);
  // One post-retry mark must reach this HUD exactly once, and no previous HUD.
  current.Player.Rigidbody.position=new Vector2(-5,-2);var target=current.Bodies.First(b=>b.BodyId==1);target.Rigidbody.position=new Vector2(-4,-2);
  foreach(var b in current.Bodies)if(b!=target)b.Rigidbody.simulated=false;
  foreach(var b in current.Bodies)if(b.TryGetComponent<EnemyMotor>(out var m))m.enabled=false;
  current.Turrets[0].enabled=false;
  int before=h.MarkNotificationCount;current.SubmitMark(1,Polarity.Model.Polarity.Positive);typeof(SimulationWorld).GetMethod("FixedUpdate",flags).Invoke(current,null);
  Check(mode+" new mark delivers one event",h.MarkNotificationCount==before+1&&current.State.RemainingMarks==2&&current.LastMarkResult.Value.Outcome==MarkOutcome.Applied);
 }
 return JsonConvert.SerializeObject(new{checks,count=checks.Count,passed=checks.Count(x=>(bool)x.GetType().GetProperty("pass").GetValue(x))});
}
return Run();

