UnityEngine.UI.Text Text(string name)=>hud.GetComponentsInChildren<UnityEngine.UI.Text>(true).First(t=>t.name==name);
Check("terminal HUD modal and counters",hud.IsBound && hud.ModalVisible && Text("Life").text=="LIFE  "+w.PlayerHealth.CurrentHealth+" / 3" && Text("Enemies").text=="ENEMIES  "+w.State.ActiveEnemyCount,new {life=Text("Life").text,enemies=Text("Enemies").text});
Check("terminal resume hidden and retry available",!hud.transform.Find("Modal/Card/ResumeButton").gameObject.activeSelf && hud.transform.Find("Modal/Card/RetryButton").gameObject.activeInHierarchy);
Check("terminal cannot resume or enter slow",!w.Level.TogglePause());w.Level.SampleControlInput(false,false,false);w.Level.SampleControlInput(true,true,false);
Check("terminal normal menu clock and empty request queue",Time.timeScale==1 && w.PendingMarkCount==0);
Check("single physical entry: attempts equal completed steps and zero failures",w.SimulationAttemptCount-startAttempts==w.CompletedStepCount-startStep && w.FailedStepCount==0,new {steps=w.CompletedStepCount-startStep,attempts=w.SimulationAttemptCount-startAttempts});

