 var texture=ScreenCapture.CaptureScreenshotAsTexture();System.IO.File.WriteAllBytes(@"D:\Code\Polarity\docs\verification\步骤10-lost画面.png",texture.EncodeToPNG());Object.Destroy(texture);
 EditorApplication.isPaused=true;done.SetResult(JsonConvert.SerializeObject(new {checks,count=checks.Count,passed=checks.Count(x=>(bool)x.GetType().GetProperty("pass").GetValue(x))}));
