using System;
using System.Linq;
using System.Threading.Tasks;
using UnityEngine;
using UnityEditor;
using Polarity.Simulation;
using Polarity.Views;
using Polarity.Model;
using Codely.Newtonsoft.Json;
async Task<string> Run(){
 EditorApplication.isPaused=false;
 SimulationWorld w=null;
 for(int i=0;i<400;i++){await Task.Delay(10);w=Object.FindObjectOfType<SimulationWorld>();if(w!=null && w.OwnsPhysics && !w.Level.IsRestarting && w.State.Phase==LevelPhase.Running)break;}
 var h=Object.FindObjectOfType<HUDView>();
 EditorApplication.isPaused=true;
 return JsonConvert.SerializeObject(new{phase=w.State.Phase.ToString(),life=w.PlayerHealth.CurrentHealth,marks=w.State.RemainingMarks,w.PendingMarkCount,w.ProcessedMarkCount,w.CompletedStepCount,scale=Time.timeScale,h.IsBound,h.MarkNotificationCount,h.PropagationNotificationCount,worlds=Object.FindObjectsOfType<SimulationWorld>().Length,huds=Object.FindObjectsOfType<HUDView>().Length,cameraRect=w.GetComponent<Polarity.Controllers.MarkingController>().WorldCamera.pixelRect.ToString(),passed=w.State.RemainingMarks==3&&w.ProcessedMarkCount==0&&w.PendingMarkCount==0&&Time.timeScale==1&&h.IsBound});
}
